
<?php

function deleteUnusedCategoryImage(PDO $pdo, ?string $imagePath): void
{
    if (!$imagePath) {
        return;
    }

    // Only accept paths generated by our upload system.
    if (!preg_match(
        '~^uploads/categories/[a-f0-9]{32}\.(jpg|png|webp)$~',
        $imagePath
    )) {
        return;
    }

    // Do not delete a file still used by another category.
    $statement = $pdo->prepare(
        "SELECT COUNT(*) FROM categories WHERE image = ?"
    );

    $statement->execute([$imagePath]);

    if ((int) $statement->fetchColumn() > 0) {
        return;
    }

    $filename = basename($imagePath);

    $fullPath = __DIR__ .
        "/../uploads/categories/" . $filename;

    if (is_file($fullPath) && !unlink($fullPath)) {
        error_log("Could not delete old category image: " . $filename);
    }
}
